def parse_metadata_block(body: str) -> dict:
    """Read the identity block back. Returns {} when absent.

    Uses the same innermost-well-formed-pair search as :func:`_metadata_bounds`
    so a reader and the writer never disagree about which block is authoritative.
    A stray BEGIN quoted in prose — with no matching END anywhere, or paired with
    an END that belongs to a different block — is not a block at all: it is
    prose that happens to contain the marker, and is read as no metadata rather
    than contributing fields (an invented parent, a fake task-id) to the result.
    """
    if not body:
        return {}
    bounds = _metadata_bounds(body)
    if bounds is None:
        return {}
    start, end = bounds
    inner = body[start + len(METADATA_BEGIN) : end - len(METADATA_END)]
    fields: dict = {}
